# Check 7: CLI end to end on a fake study root (synthetic p = 20 dataset, manifest with its hash; also a bad-hash case).
source("C:/Users/felip/OneDrive/Documents/Local_to_global_Bayesian/02_Experiments/I_2026-10-28_New_Campaign/code/lowp/enum/tests/helpers.R")
root <- file.path(TMP, "fake_study"); unlink(root, recursive = TRUE); dir.create(file.path(root, "inputs/p0020"), recursive = TRUE); dir.create(file.path(root, "manifests"))
X <- gen_design(20, "block", seed = 3); Yc <- gen_response(X, c(3, 7, 14, 16), c(1.4, -1, 1.8, -1.2), cs = c(c100 = 1, c075 = .75, c050 = .5, c035 = .35, c025 = .25))
f <- file.path(root, "inputs/p0020/p0020_S3_r007.rds")
saveRDS(list(X = X, Y = Yc, foldid = rep(1:10, 20), dataset_id = "p0020_S3_r007", p = 20L), f, compress = FALSE)
write.csv(data.frame(dataset_id = "p0020_S3_r007", file = "inputs/p0020/p0020_S3_r007.rds", file_sha256 = lowp_sha256(f)), file.path(root, "manifests/inputs_manifest_lowp.csv"), row.names = FALSE)
rs <- "C:/Program Files/R/R-4.4.1/bin/Rscript.exe"; script <- file.path(LOWP_ENUM_DIR, "run_enum_dataset.R")
out <- file.path(TMP, "fake_out"); unlink(out, recursive = TRUE)
r1 <- system2(rs, c(shQuote(script), "--dataset", "p0020_S3_r007", "--study", shQuote(root), "--outroot", shQuote(out), "--run-id", "T1", "--threads", "4"), stdout = TRUE, stderr = TRUE); cat(r1, sep = "\n")
d <- file.path(out, "results/T1/p0020/p0020_S3_r007"); print(list.files(d, all.files = TRUE, no.. = TRUE))
rec <- readRDS(file.path(d, "EXACT.rds"))
cat("sha file matches:", identical(strsplit(readLines(file.path(d, "EXACT.sha256")), " ")[[1]][1], lowp_sha256(file.path(d, "EXACT.rds"))), "\n")
cat("schema:", rec$schema, " scales:", names(rec$scales), " fields:", paste(names(rec), collapse = ","), "\n")
ref <- lowp_exact(X, list(c100 = Yc[, "c100"], c050 = Yc[, "c050"]), threads = 1)
cat("identical to direct lowp_exact (threads 1 vs 4): c100", identical(rec$scales$c100, ref$c100), " c050", identical(rec$scales$c050, ref$c050), "\n")
r2 <- system2(rs, c(shQuote(script), "--dataset", "p0020_S3_r007", "--study", shQuote(root), "--outroot", shQuote(out), "--run-id", "T1", "--threads", "4"), stdout = TRUE, stderr = TRUE); cat("rerun:", r2, sep = "\n")
# bad hash
m <- read.csv(file.path(root, "manifests/inputs_manifest_lowp.csv")); m$file_sha256 <- paste(rep("0", 64), collapse = ""); write.csv(m, file.path(root, "manifests/inputs_manifest_lowp.csv"), row.names = FALSE)
r3 <- system2(rs, c(shQuote(script), "--dataset", "p0020_S3_r007", "--study", shQuote(root), "--outroot", shQuote(out), "--run-id", "T2", "--threads", "2"), stdout = TRUE, stderr = TRUE); cat("bad manifest hash ->", tail(r3, 3), sep = "\n")
cat("T2 dir exists:", file.exists(file.path(out, "results/T2")), "\n")
